const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const header=document.querySelector('.site-header');
const menu=document.querySelector('.pet-menu-toggle');
menu.addEventListener('click',()=>{const open=header.classList.toggle('is-menu-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu')});
document.querySelectorAll('.site-header nav a').forEach(a=>a.addEventListener('click',()=>{header.classList.remove('is-menu-open');menu.setAttribute('aria-expanded','false')}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){header.classList.remove('is-menu-open');menu.setAttribute('aria-expanded','false');document.querySelectorAll('.service-detail').forEach(d=>d.hidden=true);document.querySelectorAll('.service-card-action').forEach(b=>b.setAttribute('aria-expanded','false'))}});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add(e.target.classList.contains('garden-banner')?'is-in-view':'scroll-reveal');observer.unobserve(e.target)}}),{threshold:.15});
document.querySelectorAll('.service-card,.clubhouse-photo,.clubhouse-copy,.garden-banner,.contact-section').forEach((el,i)=>{if(!reduce)el.style.animationDelay=(i%3)*.09+'s';observer.observe(el)});
const details=[['Bain & brossage','Un moment pour nettoyer le pelage et retirer les poils morts. Le soin se choisit avec le salon, selon votre compagnon.'],['Coupe & toilettage','Envie d’une coupe ? Parlons de son type de poil, de ses habitudes et du résultat souhaité. Le salon vous conseille sur le soin adapté.'],['Petites attentions','Griffes, démêlage ou entretien : expliquez-nous ses besoins au téléphone pour vérifier les soins possibles.']];
document.querySelectorAll('.service-card').forEach((card,i)=>{const panel=document.createElement('div');panel.className='service-detail';panel.hidden=true;panel.id='detail-'+i;const p=document.createElement('p');p.textContent=details[i][1];panel.append(p);const button=document.createElement('button');button.type='button';button.textContent='En parler au salon';panel.append(button);card.append(panel);const trigger=card.querySelector('.service-card-action');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls',panel.id);trigger.addEventListener('click',()=>{panel.hidden=!panel.hidden;trigger.setAttribute('aria-expanded',String(!panel.hidden))});button.addEventListener('click',()=>{document.querySelector('#service').selectedIndex=i;document.querySelector('#visit-choice').textContent='À discuter avec le salon : '+details[i][0]+'.';document.querySelector('#contact').scrollIntoView({behavior:reduce?'instant':'smooth'});panel.hidden=true;trigger.setAttribute('aria-expanded','false')})});
document.querySelector('#quick-visit').addEventListener('submit',e=>{e.preventDefault();const pet=document.querySelector('input[name="pet"]:checked').value;const name={Dog:'votre chien',Cat:'votre chat',Both:'vos compagnons'}[pet];document.querySelector('#visit-choice').textContent=document.querySelector('#service').value+' pour '+name+'. Appelez-nous pour convenir du rendez-vous.';document.querySelector('#contact').scrollIntoView({behavior:reduce?'instant':'smooth'});document.querySelector('.phone-link').focus({preventScroll:true})});
if(new URLSearchParams(location.search).has('capture')){const s=document.createElement('style');s.textContent='*,*:before,*:after{animation:none!important;transition:none!important;filter:none!important}.garden-animal,.thought-bubble{opacity:1!important;transform:none!important}';document.head.append(s);document.querySelectorAll('img').forEach(i=>i.loading='eager')}
